            for bj in range(bc1,bc2+1):
                for cc in cb[bj]:
                    for r in rb[bi]: painted.setdefault((int(r),int(cc)),set()).add(v)
    out=I.copy()
    for (r,c),cols in painted.items():
        cs_=sorted([int(x) for x in cols])
        out[r,c]=np.prod(cs_) if len(cs_)>1 else (cs_[0] if cs_ else 0)
