import numpy as np, json
def solve(I):
    I=np.array(I); h,w=I.shape
    srows=set(map(int,np.where((I==8).all(axis=1))[0])); scols=set(map(int,np.where((I==8).all(axis=0))[0]))
    rb=list(bands(srows,h)); cb=list(bands(scols,w))
    marks={}
    for r_ in range(h):
        for c_ in range(w):
            v=int(I[r_,c_])
            if v not in (0,8): marks.setdefault(v,[]).append((int(r_),int(c_)))
    painted={}
    for v,pts in marks.items():
        for i in range(len(pts)):
            for j in range(i+1,len(pts)):
                (r1,c1),(r2,c2)=pts[i],pts[j]
                if c1==c2 and bidx(r1,rb)!=bidx(r2,rb):
                    bc=bidx(c1,cb)
                    for bi in range(min(bidx(r1,rb),bidx(r2,rb)),max(bidx(r1,rb),bidx(r2,rb))+1):
                        for cell_r in rb[bi]:
                            for cc in cb[bc]:
                                painted.setdefault((cell_r,cc),set()).add(v)
                elif r1==r2 and bidx(c1,cb)!=bidx(c2,cb):
                    br=bidx(r1,rb)
                    for bj in range(min(bidx(c1,cb),bidx(c2,cb)),max(bidx(c1,cb),bidx(c2,cb))+1):
                        for cell_r in rb[br]:
                            for cc in cb[bj]:
                                painted.setdefault((cell_r,cc),set()).add(v)
    out=I.copy()
    for (r,c),cs in painted.items():
        if len(cs)>1: out[r,c]=np.prod(list(cs))
        elif cs: out[r,c]=list(cs)[0]
    return out.tolist()
